from collections import Counter

def transform(grid):
    a = [row[:] for row in grid]
    h, w = len(a), len(a[0])
    counts = Counter(v for row in a for v in row)
    bg = counts.most_common(1)[0][0]
    mark = max((v for v in counts if v != bg), key=lambda v: counts[v])
    pts = [(r,c) for r in range(h) for c in range(w) if a[r][c] == mark]
    if not pts:
        return a
    r0, r1 = min(r for r,c in pts), max(r for r,c in pts)
    c0, c1 = min(c for r,c in pts), max(c for r,c in pts)
    # Complete the horizontal and vertical rails: a row/column is active
    # when it contains an adjacent pair of marker cells, or is a bbox edge.
    for r in range(r0, r1+1):
        active = r in (r0,r1) or any(a[r][c] == mark and a[r][c+1] == mark for c in range(c0,c1))
        if active:
            for c in range(c0,c1+1):
                if a[r][c] == bg: a[r][c] = 2
    for c in range(c0, c1+1):
        active = c in (c0,c1) or any(a[r][c] == mark and a[r+1][c] == mark for r in range(r0,r1))
        if active:
            for r in range(r0,r1+1):
                if a[r][c] == bg: a[r][c] = 2
    return a
